func TestResolveBergetClient(t *testing.T) {
	t.Run("no prompt means no client", func(t *testing.T) {
		c, err := resolveBergetClient("", "anything")
		if err != nil || c != nil {
			t.Errorf("client = %v, err = %v", c, err)
		}
	})

	t.Run("prompt without a key fails before any network", func(t *testing.T) {
		t.Setenv(berget.EnvAPIKey, "")
		if _, err := resolveBergetClient("sum orders", berget.DefaultModel); err == nil {
			t.Fatal("missing key accepted")
		} else if !strings.Contains(err.Error(), berget.EnvAPIKey) {
			t.Errorf("error %q does not name %s", err, berget.EnvAPIKey)
		}
	})

	t.Run("prompt with a key builds a client for the model", func(t *testing.T) {
		t.Setenv(berget.EnvAPIKey, "test-key")
		c, err := resolveBergetClient("sum orders", "other-model")
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if c.Model() != "other-model" {
			t.Errorf("model = %q, want other-model", c.Model())
		}
	})
}

func TestIntCreateModelRequiresPrompt(t *testing.T) {
	// The global flag state leaks between executions, so reset what the
	// failed run set.
	defer func() { intCreateFlags.model = berget.DefaultModel }()

	rootCmd.SetArgs([]string{"int", "create", "hello-world", "--no-input", "--model", "other-model"})
	err := rootCmd.Execute()
	var ue *usageError
	if !errors.As(err, &ue) {
		t.Fatalf("error %v is not a usageError", err)
	}
	if !strings.Contains(err.Error(), "--model requires --prompt") {
		t.Errorf("unexpected error: %v", err)
	}
}
